class TaskBinding{record Payload(String label){}record Bound(int kind,Object queue){}static Object payload(String s){return new Payload(s);}static String[]strings(int n){String[]a=new String[n];java.util.Arrays.fill(a,"PRELOAD");return a;}static Integer[]integers(int n){Integer[]a=new Integer[n];java.util.Arrays.fill(a,-999);return a;}static Payload[]payloads(int n){Payload[]a=new Payload[n];java.util.Arrays.fill(a,new Payload("PRELOAD"));return a;}static Number[]numbers(int n){Number[]a=new Number[n];java.util.Arrays.fill(a,-999.0);return a;}static Object create(int kind,int n){return new Bound(kind,switch(kind){case 0->{DynQueue<String>q=new DynQueue<>(strings(n));yield q;}case 1->{DynQueue<Integer>q=new DynQueue<>(integers(n));yield q;}case 2->{DynQueue<Payload>q=new DynQueue<>(payloads(n));yield q;}default->{DynQueue<Number>q=new DynQueue<>(numbers(n));yield q;}});}@SuppressWarnings("unchecked")static void put(Object q,Object value){Bound b=(Bound)q;switch(b.kind){case 0->{DynQueue<String>s=(DynQueue<String>)b.queue;s.put((String)value);}case 1->{DynQueue<Integer>s=(DynQueue<Integer>)b.queue;s.put((Integer)value);}case 2->{DynQueue<Payload>s=(DynQueue<Payload>)b.queue;s.put((Payload)value);}default->{DynQueue<Number>s=(DynQueue<Number>)b.queue;s.put((Number)value);}}}@SuppressWarnings("unchecked")static Object get(Object q){Bound b=(Bound)q;return switch(b.kind){case 0->{DynQueue<String>s=(DynQueue<String>)b.queue;String value=s.get();yield value;}case 1->{DynQueue<Integer>s=(DynQueue<Integer>)b.queue;Integer value=s.get();yield value;}case 2->{DynQueue<Payload>s=(DynQueue<Payload>)b.queue;Payload value=s.get();yield value;}default->{DynQueue<Number>s=(DynQueue<Number>)b.queue;Number value=s.get();yield value;}};}}
